Dérivée p-ème d'une fonction polynôme
Le programme suivant permet de déterminer la dérivée d'ordre p d'un 	polynôme donné
écrit en langage Turbo Pascal
Program Derivee_peme;
uses wincrt;
var n,p,w,i,k, m: integer;
coef:array[1..20] of real;
Begin
Write(' entrez le dégré n = ');
Readln(n);
Write(' entrez l''ordre de la dérivée est p = ');
Readln(p);
For i:= 1 to n+1 do
Begin
Write(' entrez le coefficient coef[',i,'] = ');
Readln (coef[i]);
End;
w:=0;
if p>n then
Begin
Writeln('f^(p)(x) = 0');
end
else
begin
For k:= 1 to p do
begin
w:= w+1;
For i:= 1 to n+1 do
Begin
coef[i] := coef[i]*(i-w);
end;
end;
Write ('f^(p)(x)=',coef[p+1]:2:2);
For i:=p+2 to n+1 do
Begin
if coef[i] <>0 then
write( '+', coef[i]:2:2,'*x^',i-p-1);
end;
end;
End.
